package dev.smpcristalix.pvpcombat.listener;
import dev.smpcristalix.pvpcombat.PvPCombatPlugin;import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.service.*;import org.bukkit.Material;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;
/** PvP-tag, crystal nerf, bonus damage, abilities and combat pearl charges. */
public final class CombatListener implements Listener{private final CombatService combat;private final PearlService pearls;private final StatsService stats;private final AbilityService abilities;private PvPCombatSettings settings;public CombatListener(CombatService c,PearlService p,StatsService s,AbilityService a,PvPCombatSettings x){combat=c;pearls=p;stats=s;abilities=a;settings=x;}public void reload(PvPCombatSettings s){settings=s;}@EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void onDamage(EntityDamageByEntityEvent e){if(e.getEntity() instanceof Player v&&e.getDamager() instanceof EnderCrystal){e.setDamage(e.getDamage()*settings.endCrystalDamageMultiplier());return;}if(!(e.getEntity() instanceof Player v))return;Player a=resolve(e.getDamager());if(a==null||a.equals(v))return;combat.tag(a,v);double bonus=stats.damageBonusPercent(stats.profile(a.getUniqueId()));e.setDamage(e.getDamage()*(1+bonus/100.0));if(e.getDamager() instanceof Projectile pr){if(pr.getPersistentDataContainer().has(PvPCombatPlugin.CROSSBOW_KEY))abilities.tryCrossbow(a,v);else abilities.tryBow(a,v);return;}Material w=a.getInventory().getItemInMainHand().getType();if(w.name().endsWith("_SWORD"))abilities.trySword(a,v);else if(w.name().endsWith("_AXE"))abilities.tryAxe(a,v);}@EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void onLaunch(ProjectileLaunchEvent e){if(!(e.getEntity().getShooter() instanceof Player p))return;if(e.getEntity().getType().name().equals("ENDER_PEARL")&&combat.inCombat(p)){if(!pearls.canThrow(p)){e.setCancelled(true);p.sendMessage("§cЖемчуг на дополнительном КД PvPCombat.");return;}pearls.recordThrow(p);}}@EventHandler(ignoreCancelled=true)public void onFood(FoodLevelChangeEvent e){if(!(e.getEntity() instanceof Player p)||e.getFoodLevel()>=p.getFoodLevel())return;double r=stats.satietyReductionPercent(stats.profile(p.getUniqueId()))/100.0;if(r<=0)return;int loss=p.getFoodLevel()-e.getFoodLevel(),adjust=(int)Math.round(loss*(1-r));e.setFoodLevel(Math.max(0,p.getFoodLevel()-adjust));}private Player resolve(Entity d){if(d instanceof Player p)return p;if(d instanceof Projectile p&&p.getShooter() instanceof Player x)return x;return null;}}
